/* 【探针】子矩形旋转（[vrot] area，LOG_DEBUG）。与 [vrot] bakes 分开，
 * 因为两者一个测整幅、一个测脏区，混在一起会让 A/B 看不出趋势。 */
static void epic_rotate_area_probe(bool ok, uint32_t ms, uint32_t px)
{
  static struct
  {
    uint32_t n;
    uint32_t sum;
    uint32_t max;
    uint32_t px;
    uint32_t win;
  } pf;
  uint32_t win;

  if (pf.win == 0u)
    {
      pf.win = clock_systime_ticks();
    }
  if (ok)
    {
      pf.n++;
      pf.sum += ms;
      pf.px += px;
      if (ms > pf.max)
        {
          pf.max = ms;
        }
    }
  win = (uint32_t)(clock_systime_ticks() - pf.win);
  if (win >= 2000u)
    {
      if (pf.n > 0u)
        {
          syslog(LOG_DEBUG,
            "[vrot] area n=%u avg=%ums max=%ums px=%u win=%ums",
            (unsigned)pf.n, (unsigned)(pf.sum / pf.n), (unsigned)pf.max,
            (unsigned)(pf.px / pf.n), (unsigned)win);
        }
      pf.n = 0u;
      pf.sum = 0u;
      pf.max = 0u;
      pf.px = 0u;
      pf.win = clock_systime_ticks();
    }
}
