static bool myvendor_epic_rotate_impl(const uint16_t * src_buf,
  uint32_t src_stride, int32_t src_w, int32_t src_h, uint16_t * dst_buf,
  uint32_t dst_stride, int32_t dst_w, int32_t dst_h, int32_t angle10,
  int32_t pivot_x, int32_t pivot_y, int32_t dst_cx, int32_t dst_cy,
  int32_t clip_x, int32_t clip_y, int32_t clip_w, int32_t clip_h)
{
  EPIC_LayerConfigTypeDef layers[2];
  EPIC_LayerConfigTypeDef out;
  int32_t x0 = clip_x;
  int32_t y0 = clip_y;
  int32_t x1 = clip_x + clip_w - 1;
  int32_t y1 = clip_y + clip_h - 1;
  int32_t sy0 = src_h - 1;
  int32_t sy1 = 0;
  bool ok;

  if (src_w <= 0 || src_h <= 0 || dst_w <= 0 || dst_h <= 0
      || angle10 < 0 || angle10 >= 3600)
    {
      return false;
    }

  /* 坐标寄存器 10 bit（EPIC_COORDINATES_MAX = 1010），越界 HAL 会断言。 */
  if (src_w > EPIC_COORDINATES_MAX || src_h > EPIC_COORDINATES_MAX
      || dst_w > EPIC_COORDINATES_MAX || dst_h > EPIC_COORDINATES_MAX)
    {
      return false;
    }

  /* 目的 clip 先 clamp；完全越界 = 无事可做（不是失败）。 */
  if (x0 < 0)
    {
      x0 = 0;
    }
  if (y0 < 0)
    {
      y0 = 0;
    }
  if (x1 >= dst_w)
    {
      x1 = dst_w - 1;
    }
  if (y1 >= dst_h)
    {
      y1 = dst_h - 1;
    }
  if (x1 < x0 || y1 < y0)
    {
      return true;
    }

  /* 反投影：HAL 在 EPIC_GetRotatedArea 里把目的矩形按 `3600 - angle` 转回源坐标
   * （矩阵 [cos -sin; sin cos]，见 bf0_hal_epic.c:1048 与调用点 :860-880），
   * 即 `源 = pivot + R(-θ)·(目的 − dst_c)`。这里只关心**源的行区间**：HAL 自己会把
   * 源层裁到这块区域的 AABB 并重定 data 指针，所以只要这些行在 cache 里是干净的
   * 就行（x 方向按整行 clean，不必精确）。
   * 外扩 2 px：HAL 的 AABB 自己 ±1，最近邻取样也允许 1 px 偏差。 */
  {
    const double th = (double)angle10 * (0.1 * M_PI / 180.0);
    const double c = cos(th);
    const double s = sin(th);
    const int32_t u[4] = { x0, x1, x0, x1 };
    const int32_t v[4] = { y0, y0, y1, y1 };
    int32_t i;

    for (i = 0; i < 4; i++)
      {
        const double dx = (double)(u[i] - dst_cx);
        const double dy = (double)(v[i] - dst_cy);
        const int32_t yy =
          (int32_t)lround((double)pivot_y - s * dx + c * dy);

        if (yy < sy0)
          {
            sy0 = yy;
          }
        if (yy > sy1)
          {
            sy1 = yy;
          }
      }

    sy0 -= 2;
    sy1 += 2;
    if (sy0 < 0)
      {
        sy0 = 0;
      }
    if (sy1 >= src_h)
      {
        sy1 = src_h - 1;
      }
    if (sy1 < sy0)
      {
        /* 反投影算出了荒唐的行区间（NaN/溢出的防御）：退回整幅。 */
        sy0 = 0;
        sy1 = src_h - 1;
      }
  }

  /* EPIC 绕过 CPU 缓存直读 PSRAM：先只把**被采样的那几行**写回去。 */
  lv_epic_clean_invalidate_cache_range(
    (const uint8_t *)src_buf + (size_t)sy0 * src_stride,
    (size_t)(sy1 - sy0 + 1) * src_stride);

  /* 输出层 = 目的缓冲的 clip 矩形。⚠ `data` 必须指向 (x_offset,y_offset) 那个像素
   * （bf0_hal_epic.h:297-300 的层约定），不是缓冲基址 —— HAL 用
   * `CANVAS_TL_POS + AHB_MEM` 做画布→缓冲映射（bf0_hal_epic.c:1910-1930）。
   * 保持 x_offset/y_offset = clip 左上角，画布坐标空间就与整幅旋转时一致，
   * 源层的反投影/采样相位才不变。 */
  HAL_EPIC_LayerConfigInit(&layers[0]);
  layers[0].data = (uint8_t *)dst_buf + (size_t)y0 * dst_stride
    + (size_t)x0 * sizeof(uint16_t);
  layers[0].color_mode = EPIC_COLOR_RGB565;
  layers[0].width = (uint16_t)(x1 - x0 + 1);
  layers[0].height = (uint16_t)(y1 - y0 + 1);
  layers[0].x_offset = (int16_t)x0;
  layers[0].y_offset = (int16_t)y0;
  layers[0].total_width = MYVENDOR_EPIC_PX_PER_ROW(dst_stride);
