  layers[0].data_size = 1u;

  HAL_EPIC_LayerConfigInit(&layers[1]);          /* 前景 = 源整层 + 变换 */
  layers[1].data = (uint8_t *)src_buf;
  ...
  layers[1].data_size = 1u;

  memcpy(&out, &layers[0], sizeof(out));

  ok = (lv_epic_blend(layers, 2, &out) == HAL_OK);

  if (ok)
    {
      epic_invalidate_rect_rows(layers[0].data, dst_stride, x1 - x0 + 1,
        y1 - y0 + 1);
    }

  return ok;
}
