/* 【临时探针】每次 EPIC 图像绘制的耗时与参数，2 s 汇总一条。
 * 目的：判断旋转到底走没走 GPU、每次调用多久（配 vmap 的 `[mapfps]`）。
 * `LOG_DEBUG` ⇒ 默认静默，`ctl log all` 打开。测完即删。 */
static struct {
    uint32_t n;
    uint32_t sum;
    uint32_t max;
    uint32_t px;
    uint32_t win;
    int32_t rot;
    int st;
} s_img_pf;

static void epic_img_probe_note(uint32_t ms, int32_t rot, int32_t w, int32_t h, int st)
{
    uint32_t win;

    if (s_img_pf.win == 0u) {
        s_img_pf.win = lv_tick_get();
    }
    s_img_pf.n++;
    s_img_pf.sum += ms;
    s_img_pf.px += (uint32_t)w * (uint32_t)h;
    s_img_pf.rot = rot;
    s_img_pf.st = st;
    if (ms > s_img_pf.max) {
        s_img_pf.max = ms;
    }

    win = lv_tick_elaps(s_img_pf.win);
    if (win < 2000u) {
        return;
    }
    if (s_img_pf.n > 0u) {
        syslog(LOG_DEBUG,
            "[epicimg] n=%u px=%u blend=%ums max=%ums rot=%d.%d st=%d win=%ums",
            (unsigned)s_img_pf.n,
            (unsigned)s_img_pf.px,
            (unsigned)(s_img_pf.sum / s_img_pf.n),
            (unsigned)s_img_pf.max,
            (int)(s_img_pf.rot / 10), (int)(s_img_pf.rot % 10),
            s_img_pf.st, (unsigned)win);
    }
    s_img_pf.n = 0u;
    s_img_pf.sum = 0u;
    s_img_pf.max = 0u;
    s_img_pf.px = 0u;
    s_img_pf.win = lv_tick_get();
}

