static void vmap_rot_service(vmap_view_t * view)
{
    bool angle;
    bool dirty;

    if (view == NULL || !view->heading_up) {
        return;
    }
    /*
     * 角度待应用（want != rot），或 R 的烘焙角与当前角不一致（含烘焙失败回滚后
     * r_rot10 停在更早的值）⇒ 优先整幅：子矩形只能按 r_rot10 补，补完屏幕仍是旧朝向。
     */
    angle = (view->want_rot10 != view->rot10)
        || (view->r_rot10 != view->rot10);
    dirty = !vmap_rot_dirty_empty(view);
    if (!angle && !view->rot_pending && !dirty) {
        return;
    }
    if (view->pump_phase != 0u || view->rcanvas == NULL
        || view->render_rev == 0u
        || lv_obj_has_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN)) {
        return;                 /* 帧在飞（帧末会烘）或还没显示/还没有首帧 */
    }

    /*
     * 整幅路径（保持原语义与 1200 ms 限频）：角度待应用，或只有"整幅待补"
     * 而没有具体区域（`vmap_view_stamp_nav_then_track` 的整画布重描）。
     */
    if (angle || view->rot_full_pending || !dirty) {
        if (view->last_bake_ms != 0u
            && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
            return;             /* 限频窗口未到：下一拍再来 */
        }
        /*
         * 待应用角度与"帧外增量"合并到**同一次**重烘：否则先用旧角度烘一次增量会刷新
         * `last_bake_ms`，把角度请求一直挡在窗口外（持续记录时地图永远保持旧朝向）。
         * 角度**成功烘完才提交**：EPIC 旋转失败时保留 want_rot10，下一拍自动重试，
         * 不会把请求悄悄丢掉（否则静止时再没有别的东西会触发重烘）。
         */
        {
            const int32_t prev_rot10 = view->rot10;

            view->rot10 = view->want_rot10;
            if (!vmap_rot_full(view)) {
                view->rot10 = prev_rot10;
            }
        }
        return;
    }

    /*
     * 子矩形路径：角度没变、脏区明确 ⇒ 只重转这一块（典型 2~9 ms）。
     * 不刷新 `last_bake_ms`：子矩形不占用整幅限频窗口，否则持续增量会把角度
     * 重烘一直挡在窗口外。
     */
    if (vmap_rot_area(view)) {
        view->rot_pending = false;  /* R 已跟上 C 的脏区 */
        return;
    }

    /*
     * 原语拒绝/参数失败/脏区过大：回退整幅。
     * 回退也走**同一个 1200 ms 限频窗口**（这就是本次改动之前"每个帧外增量都整幅
     * 重烘"的行为），否则一条持续的失败路径会变成每 200 ms 一次 138 ms 的整幅；
     * 窗口内没补成的保留 rot_dirty/rot_pending，下一拍再来。
     */
    if (view->last_bake_ms != 0u
        && lv_tick_elaps(view->last_bake_ms) < VMAP_ROT_BAKE_MIN_MS) {
        return;
    }
    /*
     * 整幅也失败（EPIC 超时/参数问题）：**必须升级成"整幅待恢复"**。
     * 一次超时的整幅可能已经按新 pivot 写了一部分 R，而 r_pan/r_rot10 仍是旧基准
     * ⇒ 之后任何子矩形补丁成功都会清账，脏区外就永久留下"混合基准"的像素。
     * 置上 `rot_full_pending` 后 service 会一直尝试整幅，直到真的成功。
     */
    if (!vmap_rot_full(view)) {
        view->rot_pending = true;
        view->rot_full_pending = true;
    }
}

